/** Build the action context for a card shown in card view. */
export function cardContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[]): ActionContext {
    if (!card.header.internalId) throw new Error(`Cannot build action context without an internal ID: ${card.path}`)

    return markdownContext(card, cardTypes, 'card')
}

/**
 * Build the action context for a markdown file in the tree/text view. Regular markdown files
 * are not cards and carry no internal ID, so the context stays without card identity.
 */
export function fileContext(card: Card, cardTypes: CardTypeConfig[]): ActionContext {
    return markdownContext(card, cardTypes, 'file')
}

/** Build the action context for a folder node in the tree. */
export function folderContext(folder: string, isSpecial = false): ActionContext {
    const context: ActionContext = { folder, kind: 'folder' }
    if (isSpecial) context.type = folder

    return context
}

/** Build context for actions that run against the opened project rather than a card or file. */
export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Build context for a top-level or drill-down diagram action. */
export function diagramContext(type: 'root'): ActionContext
export function diagramContext(type: 'child', diagramId: string, diagramItemId: string, parentNode: string): ActionContext
export function diagramContext(type: 'child' | 'root', diagramId?: string, diagramItemId?: string, parentNode?: string): ActionContext {
    if (type === 'root') return { kind: 'diagram', type }
    if (!diagramId || !diagramItemId || !parentNode) throw new Error('Child diagram context requires diagram, item, and parent-node values')

    return { diagramId, diagramItemId, kind: 'diagram', parentNode, type }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree

        return unassignedContext
    }

    return { ...context, worktree: String(worktree) }
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || context[key] === action.appliesTo[key])
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    if (context.kind === 'diagram') {
        return actions.filter((action) => (
            !action.builtin
            && action.appliesTo?.kind === 'diagram'
            && actionMatchesContext(action, context)
        ))
    }

    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

import { useCallback, useSyncExternalStore } from 'react'
import {
    actionAcknowledgementEvent,
    agentAcknowledgementService,
    cardAcknowledgementEvent,
} from '../../services/agents/agent_acknowledgement_service'
import { cardAgentState, latestUnseenConversation } from '../../services/agents/card_agent_state'
import { dataService } from '../../services/data/data_service'

function subscribeToAcknowledgements(eventTypes: string[], onStoreChange: () => void) {
    for (const eventType of eventTypes) agentAcknowledgementService.addEventListener(eventType, onStoreChange)

    return () => {
        for (const eventType of eventTypes) agentAcknowledgementService.removeEventListener(eventType, onStoreChange)
    }
}

/** Reads the live conversations of a card, which a rendered card copy cannot provide. */
export function cardConversations(cardInternalId: string | null | undefined) {
    return cardInternalId ? dataService.agents.getAgentConversations(cardInternalId) : []
}

/**
 * Agent state of one card, refreshed on that card's scoped conversation events.
 * Conversations are read from the agent store on every snapshot, so newly attached or
 * acknowledged conversations are picked up without republishing the card.
 */
export function useCardAgentState(cardInternalId: string | null | undefined) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        cardInternalId
            ? subscribeToAcknowledgements([cardAcknowledgementEvent(cardInternalId)], onStoreChange)
            : () => undefined
    ), [cardInternalId])
    const getSnapshot = useCallback(() => cardAgentState(cardConversations(cardInternalId)), [cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Agent state of one card action, refreshed only by that action's scoped conversation event. */
export function useActionAgentState(cardInternalId: string | null | undefined, actionId: string) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        cardInternalId
            ? subscribeToAcknowledgements([actionAcknowledgementEvent(cardInternalId, actionId)], onStoreChange)
            : () => undefined
    ), [actionId, cardInternalId])
    const getSnapshot = useCallback(() => cardAgentState(
        cardConversations(cardInternalId).filter((conversation) => conversation.actionId === actionId),
    ), [actionId, cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Identifies the unseen conversations of the given card actions, refreshed on their scoped events. */
export function useActionsUnseenKey(cardInternalId: string | null | undefined, actionIds: string[]) {
    const actionIdsKey = [...new Set(actionIds)].sort().join(',')
    const subscribe = useCallback((onStoreChange: () => void) => {
        if (!cardInternalId) return () => undefined
        const eventTypes = actionIdsKey.split(',')
            .filter((actionId) => actionId.length > 0)
            .map((actionId) => actionAcknowledgementEvent(cardInternalId, actionId))

        return subscribeToAcknowledgements(eventTypes, onStoreChange)
    }, [actionIdsKey, cardInternalId])
    const getSnapshot = useCallback(() => {
        const conversations = cardConversations(cardInternalId)

        return actionIdsKey.split(',')
            .map((actionId) => latestUnseenConversation(conversations, actionId)?.id ?? '')
            .join(',')
    }, [actionIdsKey, cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

import type { AgentConversation } from '../../data/data_types'

export type CardAgentState = 'idle' | 'running' | 'unseen result' | 'waiting for input'

/** Newest not-yet-viewed conversation for one action, or null when all are viewed. */
export function latestUnseenConversation(conversations: AgentConversation[], actionId: string) {
    return [...conversations]
        .filter((conversation) => conversation.actionId === actionId && !conversation.viewed)
        .sort((left, right) => right.startedAt.localeCompare(left.startedAt))[0] ?? null
}

/** True when any conversation has not been viewed yet. */
export function hasUnseenConversation(conversations: AgentConversation[]) {
    return conversations.some(({ viewed }) => !viewed)
}

function isConversationWaiting(conversations: AgentConversation[]) {
    return conversations.some((conversation) => {
        if (conversation.status === 'waitingForInput') return true
        if (conversation.status !== 'running') return false

        const stateEvent = conversation.entries.findLast((entry) => (
            entry.kind === 'event' && (entry.type === 'waiting' || entry.type === 'resumed')
        ))

        return stateEvent?.kind === 'event' && stateEvent.type === 'waiting'
    })
}

/** True when the card has at least one agent conversation still running. */
export function hasRunningConversation(conversations: AgentConversation[]) {
    return conversations.some((conversation) => (
        conversation.status === 'running' || conversation.status === 'waitingForInput'
    ))
}

/** Resolve the single agent state shown for a card, mirroring the priority waiting > running > unseen > idle. */
export function cardAgentState(conversations: AgentConversation[]): CardAgentState {
    if (isConversationWaiting(conversations)) return 'waiting for input'
    if (hasRunningConversation(conversations)) return 'running'
    if (hasUnseenConversation(conversations)) return 'unseen result'

    return 'idle'
}

/** Human-readable description of an agent state, or null when idle. */
export function agentStateDescription(agentState: CardAgentState): string | null {
    if (agentState === 'waiting for input') return 'Agent is waiting for input'
    if (agentState === 'running') return 'Agent is running'
    if (agentState === 'unseen result') return 'New agent result available'

    return null
}

import { useCallback, useSyncExternalStore } from 'react'
import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import { actionRunRegistry, type ActionRun, type ActionRunStore } from '../../services/actions/action_run_registry'
import type { ActionRunBindingStore } from '../actions/run/state/action_run_binding_store'

const EMPTY_ACTIVE_RUNS: ReturnType<typeof actionRunRegistry.getGlobalActiveSnapshot> = []
const EMPTY_RUN_STORES: ActionRunStore[] = []
const subscribeEmpty = () => () => undefined
const getNullSnapshot = () => null

function useRunStore<T>(store: ActionRunStore | null, selector: (run: ActionRun | null) => T) {
    return useSyncExternalStore(
        store?.subscribe ?? subscribeEmpty,
        () => selector(store?.getSnapshot() ?? null),
        () => selector(null),
    )
}

function useActionRunStore(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoreByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )
    const store = useSyncExternalStore(
        subscribe,
        getSnapshot,
        getNullSnapshot,
    )

    return store
}

/** Subscribe to only the latest run bound to one root action and context. */
export function useActionRun(actionId: string, context: ActionContext) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, (run) => run)
}

/** Subscribe to one selected value from a scoped action run. */
export function useActionRunSelector<T>(actionId: string, context: ActionContext, selector: (run: ActionRun | null) => T) {
    const store = useActionRunStore(actionId, context)

    return useRunStore(store, selector)
}

/** Subscribe to one selected value from a run identified by runId. */
export function useRunSelector<T>(runId: string | null, selector: (run: ActionRun | null) => T) {
    const subscribe = useCallback(
        (listener: () => void) => runId ? actionRunRegistry.subscribeRun(runId, listener) : subscribeEmpty(),
        [runId],
    )
    const getSnapshot = useCallback(
        () => selector(runId ? actionRunRegistry.getRunStore(runId)?.getSnapshot() ?? null : null),
        [runId, selector],
    )

    return useSyncExternalStore(subscribe, getSnapshot, () => selector(null))
}

/** Subscribe to runId selected by one popup runtime. */
export function useBoundRunId(bindingStore: ActionRunBindingStore) {
    return useSyncExternalStore(bindingStore.subscribe, bindingStore.getSnapshot, bindingStore.getSnapshot)
}

/** Subscribe to all live run stores for one root action and context. */
export function useActionRunStores(actionId: string, context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
        (listener: () => void) => actionRunRegistry.subscribeActionRunByKey(actionId, contextIdentity, listener),
        [actionId, contextIdentity],
    )
    const getSnapshot = useCallback(
        () => actionRunRegistry.getActionRunStoresByKey(actionId, contextIdentity),
        [actionId, contextIdentity],
    )

    return useSyncExternalStore(subscribe, getSnapshot, () => EMPTY_RUN_STORES)
}

/** Subscribe to active run status summaries for one context. */
export function useActiveActionRunsForContext(context: ActionContext) {
    const contextIdentity = actionContextIdentity(context)
    const subscribe = useCallback(
